/**
 * Unit tests for MathUtils.gcd method.
 * Aiming for maximum branch and line coverage.
 */
public class MathUtils_gcd_TriageGen0Test {

















    @Test
    public void testGcdOneIsOddOneIsEven_UOdd() {
        // B2/B3: t = v (u is odd)
        // gcd(3, 6) -> u=-3, v=-6. u is odd. t = -6. 
        // Loop: t becomes -3. t is negative, so v = -3. t = (-3 - (-3))/2 = 0.
        assertEquals(3, MathUtils.gcd(3, 6));
    }






}

