/**
 * Unit tests for MathUtils.gcd method.
 * Aiming for maximum branch and line coverage.
 */
public class MathUtils_gcd_TriageGen0Test {



















    @Test
    public void testGcdOneIsOddOneIsEven_VOdd() {
        // B2/B3: t = -(u/2) (u is even, v is odd)
        // gcd(6, 3) -> u=-6, v=-3. u is even. t = -(-6/2) = 3.
        // Loop: t is 3 (odd). t > 0, so u = -3. t = (-3 - (-3))/2 = 0.
        assertEquals(3, MathUtils.gcd(6, 3));
    }




}

